/** @jsxImportSource react */

import { cn } from '@videojs/utils/style';
import type { ComponentProps, ReactNode } from 'react';

import { StatusAnnouncer } from '../shared/components/behaviors/status-announcer';
import { Container } from '../shared/components/layout/container';
import { AudioErrorDialog } from '../shared/skins/shared/audio/dialogs/error-dialog';
import { LivePlaybackHotkeys } from '../shared/skins/shared/behaviors/live-playback-hotkeys';
import { DefaultLiveAudioControls } from './layout/controls';

export interface LiveAudioSkinProps extends Omit<NonNullable<ComponentProps<typeof Container>>, 'children'> {
  children?: ReactNode;
}

export function LiveAudioSkin({ children, className, ...props }: LiveAudioSkinProps = {}) {
  return (
    <Container className={cn('audio-skin', className)} data-theme="default" data-preset="live-audio" {...props}>
      {children}
      <AudioErrorDialog />
      <DefaultLiveAudioControls />
      <LivePlaybackHotkeys />
      <StatusAnnouncer />
    </Container>
  );
}
